import React, { useState } from "react";
import "./donation-tabs.css";


export function CryptoBox({ address, qr }) {
  const [copied, setCopied] = useState(false);

  const copy = () => {
    navigator.clipboard.writeText(address);
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
  };

  return (
    <div>
      <img
        src={qr}
        alt="QR"
        style={{ marginBottom: "1rem" }}
      />

      <div
        style={{
          wordBreak: "break-all",
          cursor: "pointer",
          fontSize: "0.9rem",
          background: "#f6f6f6",
          padding: "0.7rem",
          borderRadius: "8px",
        }}
        onClick={copy}
      >
        {address} 📋 {copied && "COPIED"}
      </div>
    </div>
  );
}








export default function DonationTabs({
  paymentComponent,
  crypto1,
  crypto2,
}) {
  const [active, setActive] = useState("payment");

  return (
    <div className="donation">
      <div className="donation-tabs">
        <button
          className={active === "payment" ? "active" : ""}
          onClick={() => setActive("payment")}
        >
          Payment
        </button>
        <button
          className={active === "crypto1" ? "active" : ""}
          onClick={() => setActive("crypto1")}
        >
          Monero
        </button>
        <button
          className={active === "crypto2" ? "active" : ""}
          onClick={() => setActive("crypto2")}
        >
          Lightning
        </button>
      </div>

      <div className="donation-content">
        {active === "payment" && paymentComponent}
        {active === "crypto1" && crypto1}
        {active === "crypto2" && crypto2}
      </div>
    </div>
  );
}

